#include <iostream>
#include <unordered_map>

using namespace std;

int numOfDuplicates(int arr[], int n)
{
    unordered_map<int, int> freq;

    for (int i = 0; i < n; i++)
    {
        freq[arr[i]]++;
    }

    int count = 0;
    for (auto i : freq)
    {
        if (i.second > 1)
            count++;
    }
    return count;
}

